  | { type: 'couch'; ticket: Ticket };

interface RowModel {
  row: number;
  cells: Cell[];
}

function buildRows(): RowModel[] {
  const rows: RowModel[] = [];
  for (let row = 1; row <= ROWS; row++) {
    const cells: Cell[] = [];
    const addRange = (from: number, to: number) => {
      if (row === COUCH_ROW) {
        for (let c = from; c < to; c += 2) cells.push({ type: 'couch', ticket: makeTicket(row, c) });
