    if (cell.type !== 'seat' && cell.type !== 'couch') return 'available';
    const ids = cell.ticket.ids;
    const occupied = this.occupied();
    if (ids.some((id) => occupied.has(id))) return 'unavailable';
    const selected = this.selected();
